-- Spires of Arak, Skettis: the Darting Swift Feathers in the air fly wide loops kept clear of the terrain and of the ruins, the ones on the ground all wander
DELETE FROM `waypoint_data` WHERE `id` IN (105420100, 105420110, 105420120, 105420140, 105420220);
UPDATE `creature` SET `MovementType` = 1, `spawndist` = 8 WHERE `id` = 84013 AND `guid` NOT IN (10542010, 10542011, 10542012, 10542014, 10542022);
DELETE FROM `creature_movement_override` WHERE `SpawnId` IN (SELECT `guid` FROM `creature` WHERE `id` = 84013) AND `SpawnId` NOT IN (10542010, 10542011, 10542012, 10542014, 10542022);
